import {
  TourRoot,
  TourAnchor,
  TourTrigger,
  type TourStepDef,
} from "@/components/bevelui/tour";

const steps: TourStepDef[] = [
  {
    step: 1,
    title: "Your profile",
    description: "Update your avatar and display name here.",
    side: "bottom",
  },
  {
    step: 2,
    title: "Settings",
    description: "Notifications, billing, and team members live here.",
    side: "right",
  },
];

export default function DashboardPage() {
  return (
    <TourRoot
      steps={steps}
      onComplete={() => markOnboarded()}
      onSkip={() => track("tour_abandoned")}
    >
      <TourAnchor step={1}>
        <Avatar />
      </TourAnchor>

      <TourAnchor step={2} asChild>
        <button>Settings</button>
      </TourAnchor>

      <TourTrigger label="Take a tour" />
    </TourRoot>
  );
}

const steps: TourStepDef[] = [
  {
    step: 3,
    title: "Create your first project",
    description: "Go ahead — press the button. We'll continue once it's open.",
    side: "bottom",
    interactive: true,
  },
];

function NewProjectButton() {
  const { currentStep, next } = useTour();

  return (
    <TourAnchor step={3} asChild>
      <button
        onClick={() => {
          openProjectDialog();
          if (currentStep === 3) next();
        }}
      >
        New project
      </button>
    </TourAnchor>
  );
}

{
  step: 4,
