  description: "Invite teammates and set their roles.",
  beforeEnter: () => setSettingsMenuOpen(true),
}

const steps: TourStepDef[] = [
  {
    step: 1,
    title: "Export your data",
    description: "Download everything as CSV in one click.",
    side: "bottom",
    media: {
      type: "video", // "video" | "gif" | "image"
      src: "/demos/export.mp4",
      poster: "/demos/export-thumb.jpg",
      alt: "Exporting a table to CSV",
    },
  },
];

import { useTour } from "@/components/bevelui/tour";

function TourToolbar() {
  const {
    start,
    stop,
    next,
    prev,
    skip,
    goTo,
    currentStep,
    totalSteps,
    isOpen,
    isAnchorMissing,
  } = useTour();

  return (
    <div>
      <button onClick={start}>Start tour</button>
      <button onClick={() => goTo(3)}>Jump to step 3</button>
      <button onClick={skip}>Skip</button>
      <span>
        {currentStep} / {totalSteps}
      </span>
      {isAnchorMissing && <span>This step has no anchor on screen.</span>}
    </div>
  );
}
